package dev.macasino.game;

import java.util.UUID;

/**
 * Wheel of Fortune: pure server-side wheel-spin game logic.
 *
 * <p>A player places a bet, then the wheel spins and lands on one of 8 segments.
 * Each segment has a multiplier: [2x, 5x, 10x, 20x, 50x, 100x, 5x, 2x].
 * The payout is bet * multiplier.
 *
 * <p>The segment is generated by a server-owned {@link java.util.Random}, so a
 * client cannot influence the outcome.
 */
public class WheelOfFortuneTable {

    public static final int MIN_BET = 10;
    public static final int MAX_BET = 10_000;

    private static final long[] MULTIPLIERS = {2, 5, 10, 20, 50, 100, 5, 2};

    private final java.util.Random rng = new java.util.Random();
    private final java.util.Map<UUID, Long> bets = new java.util.concurrent.ConcurrentHashMap<>();
    private final java.util.Map<UUID, Integer> lastSegment = new java.util.concurrent.ConcurrentHashMap<>();
    private final java.util.Map<UUID, Long> lastPayout = new java.util.concurrent.ConcurrentHashMap<>();

    /** Place a bet for a player. Returns false if the stake is out of range. */
    public boolean placeBet(UUID playerId, long amount) {
        if (amount < MIN_BET || amount > MAX_BET) return false;
        bets.put(playerId, amount);
        return true;
    }

    /** Spin the wheel for a player. Returns the segment index (0..7). */
    public int spin(UUID playerId) {
        Long bet = bets.get(playerId);
        if (bet == null || bet <= 0) return -1;

        int segment = rng.nextInt(MULTIPLIERS.length);
        lastSegment.put(playerId, segment);

        long payout = bet * MULTIPLIERS[segment];
        lastPayout.put(playerId, payout);

        return segment;
    }

    /** Get the last segment for a player, or -1 if no spin has occurred. */
    public int getLastSegment(UUID playerId) {
        return lastSegment.getOrDefault(playerId, -1);
    }

    /** Get the last payout for a player, or 0 if none. */
    public long getLastPayout(UUID playerId) {
        return lastPayout.getOrDefault(playerId, 0L);
    }

    /** Get the bet amount for a player, or 0 if none. */
    public long getBet(UUID playerId) {
        return bets.getOrDefault(playerId, 0L);
    }

    /** Clear a player's bet (refund). */
    public long clearBet(UUID playerId) {
        Long bet = bets.remove(playerId);
        return bet != null ? bet : 0L;
    }
}
